import React from "react";

// ItaliaCodiceFiscaleView component
//
// A headless display component for showing Italy's
// Codice fiscale (CF) in a read-only format.
//
// Props:
//   className — string, optional. CSS class name.
//   label — string, required. Accessible label for screen readers via aria-label.
//   value — string, default "". The identifier string to display.
//   ...restProps — additional HTML attributes spread onto the <span>.
//
// Syntax:
//   <ItaliaCodiceFiscaleView label="Italian Fiscal Code" value={value} />
//
// Accessibility:
//   - aria-label provides the accessible name so screen readers announce the purpose
//
// References:
//   - https://en.wikipedia.org/wiki/Italian_fiscal_code

export interface ItaliaCodiceFiscaleViewProps {
    className?: string;
    /** Accessible label for screen readers */
    label: string;
    /** The identifier to display */
    value?: string;
    [key: string]: unknown;
}

export default function ItaliaCodiceFiscaleView({
    className = "",
    label,
    value = "",
    ...restProps
}: ItaliaCodiceFiscaleViewProps) {
    return (
        <span
            className={`italia-codice-fiscale-view ${className}`}
            aria-label={label}
            {...restProps}
        >
            {value}
        </span>
    );
}
